  from jsonb_array_elements('[{"n":29,"t":"assess_parts","p":"The number of bacteria in a dish is modelled by N = 300 × 2^t, where t is in hours.\n\n(a) State the initial number of bacteria.\n(b) Calculate the number of bacteria after 5 hours.\n(c) Using logarithms, calculate the time for the population to reach 20 000, to 2 decimal places.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The number of bacteria in a dish is modelled by N = 300 × 2^t, where t is in hours."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the initial number of bacteria.\n(b) Calculate the number of bacteria after 5 hours.\n(c) Using logarithms, calculate the time for the population to reach 20 000, to 2 decimal places."}]}]},"e":"N(0) = 300 and N(5) = 9 600. For 20 000, 2^t = 66.67 so t = log 66.67 / log 2 ≈ 6.06 hours.","m":8,"df":"hard","tp":"exponential equations","st":"exponential equations","cfg":{"source":"myp-mock-myp5-mock","question_number":29,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"To solve for an exponent, isolate the power and take logarithms of both sides.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the initial number of bacteria.","kind":"numeric","points":1,"hints":["Substitute t = 0.","2^0 = 1."],"strand":"C(i)","answer":300,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the number of bacteria after 5 hours.","kind":"numeric","points":2,"hints":["Substitute t = 5.","300 × 32."],"strand":"C(ii)","answer":9600,"tolerance":0,"unit":"bacteria"},{"id":"c","label":"(c)","prompt":"State the value of 20 000 ÷ 300, to 3 significant figures.","kind":"numeric","points":2,"hints":["Divide the target by the initial population.","This equals 2^t."],"strand":"C(iii)","answer":66.7,"tolerance":0.1},{"id":"d","label":"(d)","prompt":"Calculate the time to reach 20 000 bacteria, to 2 decimal places.","kind":"numeric","points":3,"hints":["Take logarithms of both sides: t = log(66.67) ÷ log(2).","Your answer should be a little more than 6 hours."],"strand":"C(iv)","answer":6.06,"tolerance":0.03,"unit":"hours"}],"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Show the logarithm step in (d); the division only sets up the equation."},"marking":"(a) 1 mark. (b) 2 marks: 1 for 2^5, 1 for 9 600. (c) 2 marks: 1 for the division, 1 for 66.7. (d) 3 marks: 1 for the log equation, 1 for the evaluated logarithms, 1 for 6.06."},{"n":30,"t":"assess_parts","p":"A ball is thrown upwards. Its height in metres after t seconds is h = 20t − 5t².\n\n(a) Calculate the height after 1 second.\n(b) Show that the ball returns to the ground at t = 4.\n(c) State the time at which the ball reaches its maximum height.\n(d) Calculate the maximum height.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ball is thrown upwards. Its height in metres after t seconds is h = 20t − 5t²."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Calculate the height after 1 second.\n(b) Show that the ball returns to the ground at t = 4.\n(c) State the time at which the ball reaches its maximum height.\n(d) Calculate the maximum height."}]}]},"e":"h(1) = 15 m; the roots are t = 0 and t = 4; the vertex is at t = 2 giving h = 20 m. Beyond t = 4 the formula produces negative heights, so the physical model stops at the landing time.","m":9,"df":"hard","tp":"quadratic functions","st":"quadratic functions","cfg":{"source":"myp-mock-myp5-mock","question_number":30,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For a quadratic model, roots give the start and end, and the vertex lies halfway between them.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"Calculate the height after 1 second, in metres.","kind":"numeric","points":1,"hints":["Put t = 1 into the height equation, taking care with the squared term.","20(1) − 5(1)²."],"strand":"D(i)","answer":15,"tolerance":0,"unit":"m"},{"id":"b","label":"(b)","prompt":"State the non-zero time at which the ball returns to the ground.","kind":"numeric","points":2,"hints":["Set h = 0 and factorise.","5t(4 − t) = 0."],"strand":"D(ii)","answer":4,"tolerance":0,"unit":"s"},{"id":"c","label":"(c)","prompt":"State the time of maximum height, in seconds.","kind":"numeric","points":2,"hints":["The maximum is halfway between the two roots.","Half of 4."],"strand":"D(iii)","answer":2,"tolerance":0,"unit":"s"},{"id":"d","label":"(d)","prompt":"Calculate the maximum height, in metres.","kind":"numeric","points":2,"hints":["Substitute t = 2 into the height equation.","40 − 20."],"strand":"D(iv)","answer":20,"tolerance":0,"unit":"m"},{"id":"e","label":"(e)","prompt":"Explain why the model cannot be used for t = 5.","kind":"text","points":2,"hints":["What does the equation give at t = 5?","Can a ball be below the ground?"],"strand":"D(iv)","accepted":["at t = 5 the equation gives −25 m, a negative height, and the ball has already landed, so the model only applies until t = 4"],"keywords":[["equation"],["gives"],["negative"],["height"],["ball"],["already"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range.","marking_criteria":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range.","response_tools":["graph","rich_text","math"],"response_requirement":"graph","response_guidance":"Plot h = 20t − 5t² in the workspace and read the vertex from the graph to check (c) and (d)."},"marking":"(a) 1 mark. (b) 2 marks: 1 for factorising, 1 for t = 4. (c) 2 marks: 1 for the midpoint, 1 for 2 s. (d) 2 marks: 1 for substituting, 1 for 20 m. (e) 2 marks: 1 for the negative height, 1 for the valid range."},{"n":31,"t":"assess_parts","p":"The loudness of a sound in decibels is L = 10 log₁₀(I / I₀), where I₀ is the threshold of hearing.\n\n(a) State the loudness when I = 1 000 I₀.\n(b) State the loudness when I = 10 000 I₀.\n(c) Explain why multiplying the intensity by 10 adds exactly 10 decibels.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The loudness of a sound in decibels is L = 10 log₁₀(I / I₀), where I₀ is the threshold of hearing."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the loudness when I = 1 000 I₀.\n(b) State the loudness when I = 10 000 I₀.\n(c) Explain why multiplying the intensity by 10 adds exactly 10 decibels."}]}]},"e":"1000 I₀ gives 30 dB and 10 000 I₀ gives 40 dB. Since log(10x) = log x + 1, each tenfold increase in intensity adds 10 dB, which is why decibels are a logarithmic scale.","m":5,"df":"hard","tp":"logarithms","st":"logarithms","cfg":{"source":"myp-mock-myp5-mock","question_number":31,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"A logarithmic scale turns multiplication into addition: a constant factor becomes a constant difference.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the loudness when I = 1 000 I₀, in decibels.","kind":"numeric","points":1,"hints":["The ratio I/I₀ is 1000.","10 × log(1000) and log(1000) = 3."],"strand":"C(i)","answer":30,"tolerance":0,"unit":"dB"},{"id":"b","label":"(b)","prompt":"State the loudness when I = 10 000 I₀, in decibels.","kind":"numeric","points":1,"hints":["The intensity ratio is now 10 000.","log(10 000) = 4, so evaluate 10 × 4."],"strand":"C(i)","answer":40,"tolerance":0,"unit":"dB"},{"id":"c","label":"(c)","prompt":"Explain why a tenfold increase in intensity adds 10 dB.","kind":"text","points":3,"hints":["Use log(10x) = log x + 1.","The formula multiplies the logarithm by 10."],"strand":"C(ii)","accepted":["multiplying the intensity by ten adds 1 to the logarithm, and the formula multiplies the logarithm by 10, so the loudness rises by exactly 10 dB"],"keywords":[["multiplying"],["intensity"],["adds"],["logarithm"],["formula"],["multiplies"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion.","marking_criteria":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Quote the logarithm law you use in (c); the mark is for the law, not the arithmetic."},"marking":"(a) 1 mark. (b) 1 mark. (c) 3 marks: 1 for the log law, 1 for the ×10 in the formula, 1 for the 10 dB conclusion."},{"n":32,"t":"assess_parts","p":"A car loses 15% of its value each year. It cost $24 000 when new.\n\n(a) State the multiplier for one year of depreciation.\n(b) Calculate the value after 3 years, to the nearest dollar.\n(c) Calculate the number of complete years after which the value first falls below $8 000, testing successive years.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A car loses 15% of its value each year. It cost "},{"type":"text","text":"$24 000 when new."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the multiplier for one year of depreciation.\n(b) Calculate the value after 3 years, to the nearest dollar.\n(c) Calculate the number of complete years after which the value first falls below "},{"type":"text","text":"$8 000, testing successive years."}]}]},"e":"Multiplier 0.85. Value after 3 years $14 739 and after 6 years $9 052. After 7 years 9 052 × 0.85 ≈ $7 694, the first value below $8 000.","m":9,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":32,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For ''when does the value fall below X'', compute successive values and bracket the threshold.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the depreciation multiplier for one year.","kind":"numeric","points":1,"hints":["A 15% loss leaves 85% of the value.","Write 85% as a decimal."],"strand":"D(i)","answer":0.85,"tolerance":0.001},{"id":"b","label":"(b)","prompt":"Calculate the value after 3 years, to the nearest dollar.","kind":"numeric","points":3,"hints":["Use 24000 × 0.85^3.","0.85³ = 0.614125."],"strand":"D(ii)","answer":14739,"tolerance":1,"unit":"$"},{"id":"c","label":"(c)","prompt":"Calculate the value after 6 years, to the nearest dollar.","kind":"numeric","points":3,"hints":["0.85^6 ≈ 0.37715.","24000 × 0.37715."],"strand":"D(iii)","answer":9052,"tolerance":3,"unit":"$"},{"id":"d","label":"(d)","prompt":"State the number of complete years before the value first falls below $8 000.","kind":"numeric","points":2,"hints":["Your 6-year value is still above 8000.","Multiply by 0.85 once more and compare."],"strand":"D(iv)","answer":7,"tolerance":0,"unit":"years"}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7.","response_tools":["rich_text","math","table"],"response_requirement":"text","response_guidance":"Tabulate the year-by-year values in the workspace; (d) needs the bracketing years, not a guess."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the power, 1 for 0.614125, 1 for $14 739. (c) 3 marks: 1 for the sixth power, 1 for the product, 1 for $9 052. (d) 2 marks: 1 for the 7th year value, 1 for 7."},{"n":33,"t":"assess_parts","p":"In a geometric sequence the first term is 8 and the common ratio is 1/2.\n\n(a) Write the first four terms.\n(b) Calculate the sum of the first 6 terms.\n(c) Calculate the sum to infinity.\n(d) Explain why the sum of the first 6 terms is already close to the sum to infinity.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a geometric sequence the first term is 8 and the common ratio is 1/2."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) Write the first four terms.\n(b) Calculate the sum of the first 6 terms.\n(c) Calculate the sum to infinity.\n(d) Explain why the sum of the first 6 terms is already close to the sum to infinity."}]}]},"e":"Terms 8, 4, 2, 1, 0.5, 0.25 give S_6 = 15.75 and S∞ = 16; the missing tail is exactly 0.25, the seventh term onwards, which halves away rapidly.","m":9,"df":"hard","tp":"geometric sequences","st":"geometric sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":33,"paper_section":"B","myp_criterion":"D","strand":"D(i)","next_time_hint":"For |r| < 1 the tail after n terms is r^n/(1 − r) times the first term: it shrinks geometrically.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the 4th term.","kind":"numeric","points":1,"hints":["Multiply by 1/2 for each successive term.","8, 4, 2, then one more halving."],"strand":"D(i)","answer":1,"tolerance":0},{"id":"b","label":"(b)","prompt":"Calculate the sum of the first 6 terms.","kind":"numeric","points":3,"hints":["Use S_n = a(1 − r^n)/(1 − r).","8(1 − 1/64)/(0.5)."],"strand":"D(ii)","answer":15.75,"tolerance":0.02},{"id":"c","label":"(c)","prompt":"Calculate the sum to infinity.","kind":"numeric","points":2,"hints":["S∞ = a/(1 − r) because |r| < 1.","8 ÷ 0.5."],"strand":"D(iii)","answer":16,"tolerance":0},{"id":"d","label":"(d)","prompt":"Explain why six terms already give almost the whole sum.","kind":"text","points":3,"hints":["Compare your two sums.","What size is the remaining tail after six terms?"],"strand":"D(iv)","accepted":["the sixth term is only 0.25 and every later term is smaller still, so the tail beyond six terms adds just 0.25 to reach 16"],"keywords":[["sixth"],["term"],["later"],["smaller"],["tail"],["beyond"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"Keep the fraction 63/64 in (b) until the last step; the exact form makes (d) easy."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 63/64, 1 for 15.75. (c) 2 marks: 1 for the formula, 1 for 16. (d) 3 marks: 1 for the comparison, 1 for the 0.25 tail, 1 for the halving argument."},{"n":34,"t":"assess_parts","p":"A ladder has rungs whose lengths form an arithmetic sequence. The bottom rung is 60 cm and each rung above it is 2 cm shorter. There are 14 rungs.\n\n(a) State the length of the top rung.\n(b) Calculate the total length of timber needed for all 14 rungs.\n(c) Explain why the average rung length is the mean of the top and bottom rungs.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ladder has rungs whose lengths form an arithmetic sequence. The bottom rung is 60 cm and each rung above it is 2 cm shorter. There are 14 rungs."}]},{"type":"paragraph","content":[{"type":"text","text":"(a) State the length of the top rung.\n(b) Calculate the total length of timber needed for all 14 rungs.\n(c) Explain why the average rung length is the mean of the top and bottom rungs."}]}]},"e":"Top rung 34 cm gives S_14 = 7(94) = 658 cm and a mean of 47 cm. In an arithmetic sequence the symmetric pairs all have the same total, so the mean is the average of the end terms.","m":8,"df":"hard","tp":"arithmetic sequences","st":"arithmetic sequences","cfg":{"source":"myp-mock-myp5-mock","question_number":34,"paper_section":"B","myp_criterion":"C","strand":"C(i)","next_time_hint":"An arithmetic mean of the end terms works because of the symmetry of equal steps; say so explicitly.","assessment_style":"myp_mock","mock_exam_key":"myp5-mock","parts":[{"id":"a","label":"(a)","prompt":"State the length of the top rung, in centimetres.","kind":"numeric","points":1,"hints":["13 steps of 2 cm separate the 1st and 14th rungs.","60 − 2(13)."],"strand":"C(i)","answer":34,"tolerance":0,"unit":"cm"},{"id":"b","label":"(b)","prompt":"Calculate the total length of timber, in centimetres.","kind":"numeric","points":3,"hints":["The rung lengths form an arithmetic series: S_n = n/2 × (first + last).","There are 14 rungs, so evaluate 7 × 94."],"strand":"C(ii)","answer":658,"tolerance":0,"unit":"cm"},{"id":"c","label":"(c)","prompt":"State the mean rung length, in centimetres.","kind":"numeric","points":1,"hints":["The mean is the total divided by 14.","Or use (60 + 34)/2."],"strand":"C(iii)","answer":47,"tolerance":0,"unit":"cm"},{"id":"d","label":"(d)","prompt":"Explain why the mean equals the average of the end rungs.","kind":"text","points":3,"hints":["Write the terms and pair the first with the last.","Do the pairs have equal sums?"],"strand":"C(iv)","accepted":["in an arithmetic sequence the terms are evenly spaced, so first plus last equals second plus second-last and so on; every pair has the same sum, making the mean the average of the two end terms"],"keywords":[["arithmetic"],["sequence"],["terms"],["evenly"],["spaced"],["first"]],"minKeywordGroups":4}],"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion.","marking_criteria":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion.","response_tools":["rich_text","math"],"response_requirement":"text","response_guidance":"The pairing argument in (d) is what earns the marks — not a numerical example."},"marking":"(a) 1 mark. (b) 3 marks: 1 for the formula, 1 for 94, 1 for 658. (c) 1 mark. (d) 3 marks: 1 for even spacing, 1 for the pairing, 1 for the conclusion."}]'::jsonb) as x
